/**
 * Supported currencies for item listings and bidder display prices.
 *
 * @trace DSN-012 REQ-001 REQ-005
 */
export enum Currency { CHF = 'CHF', EUR = 'EUR', USD = 'USD' }

/**
 * Lifecycle state of an item auction.
 *
 * @trace DSN-013 REQ-001 REQ-004
 */
export enum AuctionStatus {
  open = 'open',
  closed = 'closed',
  unsold = 'unsold',
}

/**
 * User identified by unique display name.
 *
 * @trace DSN-014 REQ-008
 */
export class User {
  /**
   * Creates a user and rejects a display name outside 2 to 20 characters.
   * @throws Error when the display name is shorter than 2 or longer than 20 characters.
   */
  constructor(public id: string, public displayName: string) {
    if (displayName.length < 2 || displayName.length > 20) {
      throw new Error('Display name must be between 2 and 20 characters');
    }
  }
}

import { Item } from './Item.js';
import { Currency } from './Currency.js';

/**
 * Item as shown to a client, with optional converted prices.
 *
 * @trace DSN-017 REQ-005 REQ-010
 */
export interface ItemView {
  item: Item;
  displayCurrency: Currency | null;
  convertedStartingPrice: number | null;
  convertedHighestBid: number | null;
}

import { User } from './User.js';
import { UserService } from './UserService.js';

/**
 * HTTP-facing controller for user registration by display name.
 *
 * @trace DSN-018 REQ-008
 */
export class UserController {
  constructor(private readonly userService: UserService) {}

  /** Registers a display name and returns the user; throws if the name is invalid or taken. */
  async register(displayName: string): Promise<User> {
    return this.userService.register(displayName);
  }
}

/**
 * Accepted bid stored in item currency.
 *
 * @trace DSN-016 REQ-002
 */
export class Bid {
  constructor(public id: string, public itemId: string, public bidderId: string, public amount: number, public placedAt: Date) {}
}

/**
 * Accepted bid stored in item currency.
 *
 * @trace DSN-016 REQ-002
 */
export class Bid {
  constructor(public id: string, public itemId: string, public bidderId: string, public amount: number, public placedAt: Date) {}
}

import { randomUUID } from 'node:crypto';
import { User } from './User.js';
import { UserStore } from './UserStore.js';

/**
 * Validates display names and issues one user id per name.
 *
 * @trace DSN-021 REQ-008
 */
export class UserService {
  /**
   * Creates the service over the given user store.
   */
  constructor(private readonly userStore: UserStore) {}

  /**
   * Registers a display name and returns its user, throwing when the name is invalid or already taken.
   */
  async register(displayName: string): Promise<User> {
    if (typeof displayName !== 'string') {
      throw new Error('displayName must be a string');
    }
    const name = displayName.trim();
    if (name.length < 2 || name.length > 20) {
      throw new Error('displayName must be between 2 and 20 characters');
    }
    const existing = await this.userStore.findByName(name);
    if (existing !== null) {
      throw new Error(`displayName ${name} is already taken`);
    }
    return this.userStore.save(new User(randomUUID(), name));
  }
}

import { Currency } from './Currency.js';
import { AuctionStatus } from './AuctionStatus.js';

const LATE_BID_WINDOW_MS = 2 * 60 * 1000;

/**
 * Auction item, with prices in the item currency.
 *
 * @trace DSN-015 REQ-001 REQ-002 REQ-004 REQ-009
 */
export class Item {
  constructor(public id: string, public sellerId: string, public title: string, public startingPrice: number, public currency: Currency, public endTime: Date, public status: AuctionStatus, public highestBidAmount: number | null, public highestBidderId: string | null, public winnerId: string | null) {}

  /** Returns true when the status is open and the end time has not been reached at the given moment. */
  isOpen(now: Date): boolean {
    return this.status === AuctionStatus.open && now.getTime() < this.endTime.getTime();
  }

  /** Returns the lowest amount accepted as the next bid: the starting price, or one unit above the highest bid. */
  minimumBid(): number {
    if (this.highestBidAmount === null) {
      return this.startingPrice;
    }
    return this.highestBidAmount + 1;
  }

  /** Moves the end time 2 minutes later when now is within the last 2 minutes before it; throws when the item is not open. */
  extendIfLate(now: Date): boolean {
    if (this.status !== AuctionStatus.open) {
      throw new Error(`Item ${this.id} is not open`);
    }
    const remaining = this.endTime.getTime() - now.getTime();
    if (remaining < 0 || remaining > LATE_BID_WINDOW_MS) {
      return false;
    }
    this.endTime = new Date(this.endTime.getTime() + LATE_BID_WINDOW_MS);
    return true;
  }
}

import { Bid } from './Bid.js';
import { BidService } from './BidService.js';

/**
 * HTTP route POST /items/:id/bids, which accepts bids on open auction items.
 * @trace DSN-020 REQ-002
 */
export class BidController {
  constructor(private readonly bidService: BidService) {}

  /** Validates the bid input and places it through the bid service; throws an Error for invalid input or when the service rejects the bid. */
  async placeBid(itemId: string, userId: string, amount: number): Promise<Bid> {
    if (typeof itemId !== 'string' || itemId.length === 0) {
      throw new Error('itemId must be a non-empty string');
    }
    if (typeof userId !== 'string' || userId.length === 0) {
      throw new Error('userId must be a non-empty string');
    }
    if (typeof amount !== 'number' || !Number.isFinite(amount)) {
      throw new Error('amount must be a finite number');
    }
    return this.bidService.placeBid(itemId, userId, amount);
  }
}

import { Item } from './Item.js';
import { ItemView } from './ItemView.js';
import { ItemService } from './ItemService.js';
import { ExchangeRateService } from '../exchange-rates/ExchangeRateService.js';
import { Currency } from './Currency.js';

/**
 * HTTP-facing controller logic for listing, reading and browsing auction items.
 * @trace DSN-019 REQ-001 REQ-005 REQ-004
 */
export class ItemController {
  constructor(private readonly itemService: ItemService, private readonly exchangeRateService: ExchangeRateService) {}

  /** Lists a new item for a seller; throws when a field is missing or the currency is not CHF, EUR or USD. */
  async listItem(userId: string, title: string, startingPrice: number, endTime: string, currency: string): Promise<Item> {
    this.requireText(userId, 'userId');
    this.requireText(title, 'title');
    if (typeof startingPrice !== 'number' || !Number.isFinite(startingPrice) || startingPrice <= 0) {
      throw new Error('startingPrice must be a positive number');
    }
    if (typeof endTime !== 'string' || endTime.trim() === '') {
      throw new Error('endTime is required');
    }
    const end = new Date(endTime);
    if (Number.isNaN(end.getTime())) {
      throw new Error('endTime must be a valid date');
    }
    this.requireCurrency(currency);
    return this.itemService.listItem(userId, title, startingPrice, end, currency);
  }

  /** Returns an item with prices converted to the display currency when one is given; throws when the id is invalid or the item is not found. */
  async getItem(id: string, displayCurrency: string | undefined): Promise<ItemView> {
    this.requireText(id, 'id');
    const item = await this.itemService.getItem(id);
    if (displayCurrency === undefined) {
      return { item, displayCurrency: null, convertedStartingPrice: null, convertedHighestBid: null };
    }
    this.requireCurrency(displayCurrency);
    const target = displayCurrency as Currency;
    const convertedStartingPrice = await this.exchangeRateService.convert(item.startingPrice, item.currency, target);
    const convertedHighestBid =
      item.highestBidAmount === null
        ? null
        : await this.exchangeRateService.convert(item.highestBidAmount, item.currency, target);
    return { item, displayCurrency: target, convertedStartingPrice, convertedHighestBid };
  }

  /** Returns all auction items that are currently open for bids. */
  async listOpenItems(): Promise<Item[]> {
    return this.itemService.listOpenItems();
  }

  private requireText(value: string, name: string): void {
    if (typeof value !== 'string' || value.trim() === '') {
      throw new Error(`${name} must be a non-empty string`);
    }
  }

  private requireCurrency(value: string | undefined): void {
    if (value === undefined || !(Object.values(Currency) as string[]).includes(value)) {
      throw new Error('currency must be one of CHF, EUR, USD');
    }
  }
}

import { ItemService } from './ItemService.js';

/**
 * Periodic job that closes auctions whose end time was reached.
 *
 * @trace DSN-024 REQ-004
 */
export class AuctionCloser {
  constructor(private readonly itemService: ItemService, public intervalMs: number) {}

  /** Closes every auction whose end time has been reached, recording winners or unsold items. */
  async tick(): Promise<void> {
    await this.itemService.closeDueAuctions(new Date());
  }
}

import { Currency } from '../auction-api/Currency.js';
import { FrankfurterClient } from './FrankfurterClient.js';

interface CachedRates {
  rates: Record<string, number>;
  fetchedAt: number;
}

/**
 * Converts prices for display using exchange rates cached for a fixed time, returning null when no rate is available.
 * @trace DSN-025 REQ-005 REQ-010
 */
export class ExchangeRateService {
  private readonly cache = new Map<Currency, CachedRates>();

  constructor(private readonly frankfurterClient: FrankfurterClient, public cacheTtlMs: number) {}

  /** Converts an amount from one display currency to another, or returns null when no valid rate exists; throws on invalid input. */
  async convert(amount: number, from: Currency, to: Currency): Promise<number | null> {
    if (!Number.isFinite(amount) || amount < 0) {
      throw new Error('amount must be a non-negative finite number');
    }
    if (!Object.values(Currency).includes(from)) {
      throw new Error(`from currency ${String(from)} is not supported`);
    }
    if (!Object.values(Currency).includes(to)) {
      throw new Error(`to currency ${String(to)} is not supported`);
    }
    if (from === to) {
      return amount;
    }
    const rates = await this.getRates(from);
    if (rates === null) {
      return null;
    }
    const rate = rates[to];
    if (typeof rate !== 'number' || !Number.isFinite(rate)) {
      return null;
    }
    return Math.round(amount * rate * 100) / 100;
  }

  /** Returns rates for a base currency from the cache when fresh, otherwise fetches them; returns null when unavailable. */
  private async getRates(base: Currency): Promise<Record<string, number> | null> {
    const now = Date.now();
    const cached = this.cache.get(base);
    if (cached && now - cached.fetchedAt < this.cacheTtlMs) {
      return cached.rates;
    }
    try {
      const rates = await this.frankfurterClient.fetchRates(base);
      this.cache.set(base, { rates, fetchedAt: now });
      return rates;
    } catch {
      return null;
    }
  }
}

import { randomUUID } from 'node:crypto';
import { Item } from './Item.js';
import { ItemStore } from './ItemStore.js';
import { UserStore } from './UserStore.js';
import { AuctionEventPublisher } from './AuctionEventPublisher.js';
import { Currency } from './Currency.js';
import { AuctionStatus } from './AuctionStatus.js';

/**
 * Creates and reads items, closes due auctions.
 *
 * @trace DSN-022 REQ-001 REQ-004
 */
export class ItemService {
  constructor(
    private readonly itemStore: ItemStore,
    private readonly userStore: UserStore,
    private readonly auctionEventPublisher: AuctionEventPublisher,
  ) {}

  /** Lists a new open item for an existing seller; throws on invalid input or unknown seller. */
  async listItem(sellerId: string, title: string, startingPrice: number, endTime: Date, currency: string): Promise<Item> {
    if (typeof sellerId !== 'string' || sellerId.trim() === '') {
      throw new Error('sellerId must be a non-empty string');
    }
    if (typeof title !== 'string' || title.trim() === '') {
      throw new Error('title must be a non-empty string');
    }
    if (typeof startingPrice !== 'number' || !Number.isFinite(startingPrice) || startingPrice < 0) {
      throw new Error('startingPrice must be a non-negative number');
    }
    if (!(endTime instanceof Date) || Number.isNaN(endTime.getTime())) {
      throw new Error('endTime must be a valid date');
    }
    if (endTime.getTime() <= Date.now()) {
      throw new Error('endTime must be in the future');
    }
    if (!Object.values(Currency).includes(currency as Currency)) {
      throw new Error('currency must be one of CHF, EUR, USD');
    }
    const seller = await this.userStore.findById(sellerId);
    if (seller === null) {
      throw new Error(`User ${sellerId} not found`);
    }
    const item = new Item(
      randomUUID(),
      sellerId,
      title,
      startingPrice,
      currency as Currency,
      endTime,
      AuctionStatus.open,
      null,
      null,
      null,
    );
    return this.itemStore.saveItem(item);
  }

  /** Returns the item with the given id; throws if the id is empty or the item is not found. */
  async getItem(id: string): Promise<Item> {
    if (typeof id !== 'string' || id.trim() === '') {
      throw new Error('id must be a non-empty string');
    }
    const item = await this.itemStore.findItem(id);
    if (item === null) {
      throw new Error(`Item ${id} not found`);
    }
    return item;
  }

  /** Returns all items whose auctions are currently open. */
  async listOpenItems(): Promise<Item[]> {
    return this.itemStore.findOpenItems();
  }

  /** Closes every open item whose end time has been reached, recording the winner or marking it unsold, and publishes each closure. */
  async closeDueAuctions(now: Date): Promise<void> {
    if (!(now instanceof Date) || Number.isNaN(now.getTime())) {
      throw new Error('now must be a valid date');
    }
    const due = await this.itemStore.findDueItems(now);
    for (const item of due) {
      if (item.status !== AuctionStatus.open) {
        continue;
      }
      if (item.highestBidderId === null) {
        item.status = AuctionStatus.unsold;
        item.winnerId = null;
      } else {
        item.status = AuctionStatus.closed;
        item.winnerId = item.highestBidderId;
      }
      const saved = await this.itemStore.saveItem(item);
      await this.auctionEventPublisher.publishAuctionClosed(saved);
    }
  }
}

import { randomUUID } from 'node:crypto';
import { Bid } from './Bid.js';
import { ItemStore } from './ItemStore.js';
import { BidEventPublisher } from './BidEventPublisher.js';
import { UserStore } from './UserStore.js';

type Item = NonNullable<Awaited<ReturnType<ItemStore['findItem']>>>;

const LATE_BID_WINDOW_MS = 2 * 60 * 1000;
const EXTENSION_MS = 2 * 60 * 1000;
const MIN_INCREMENT = 1;

/**
 * Validates and stores bids, extends auction end times and publishes accepted bids to the event feed.
 * @trace DSN-023 REQ-002 REQ-009 REQ-003 REQ-011
 */
export class BidService {
  /** Validates a bid, stores it, extends a late auction and publishes it; throws on invalid input or when not found. */
  constructor(
    private readonly itemStore: ItemStore,
    private readonly bidEventPublisher: BidEventPublisher,
    private readonly userStore: UserStore,
  ) {}

  /** Places a bid on an open item; throws if ids or amount are invalid, the item or bidder is not found, or the bid is rejected. */
  async placeBid(itemId: string, bidderId: string, amount: number): Promise<Bid> {
    if (typeof itemId !== 'string' || itemId.length === 0) {
      throw new Error('itemId must be a non-empty string');
    }
    if (typeof bidderId !== 'string' || bidderId.length === 0) {
      throw new Error('bidderId must be a non-empty string');
    }
    if (typeof amount !== 'number' || !Number.isFinite(amount) || amount <= 0) {
      throw new Error('amount must be a positive number');
    }

    const item: Item | null = await this.itemStore.findItem(itemId);
    if (item === null) {
      throw new Error(`Item ${itemId} not found`);
    }
    const bidder = await this.userStore.findById(bidderId);
    if (bidder === null) {
      throw new Error(`User ${bidderId} not found`);
    }

    const now = new Date();
    const endTime = new Date(item.endTime).getTime();
    if (now.getTime() >= endTime) {
      throw new Error(`Item ${itemId} auction has ended`);
    }
    if (item.sellerId === bidderId) {
      throw new Error('Seller cannot bid on their own item');
    }

    const highest = item.highestBid ?? null;
    if (highest === null) {
      if (amount < item.startingPrice) {
        throw new Error(`First bid must be at least the starting price ${item.startingPrice}`);
      }
    } else if (amount < highest + MIN_INCREMENT) {
      throw new Error(`Bid must be at least ${MIN_INCREMENT} higher than the current highest bid ${highest}`);
    }

    const bid = new Bid(randomUUID(), itemId, bidderId, amount, now);
    await this.itemStore.saveBid(bid);

    item.highestBid = amount;
    if (endTime - now.getTime() <= LATE_BID_WINDOW_MS) {
      item.endTime = new Date(endTime + EXTENSION_MS);
    }
    await this.itemStore.saveItem(item);

    await this.bidEventPublisher.publishBidAccepted(bid, item);
    return bid;
  }
}

import { DatabaseSync } from 'node:sqlite';
import { User } from './User.js';

/**
 * Stores users in the API server's SQLite database, keyed by id and unique by display name.
 * @trace DSN-028 REQ-008
 */
export class UserStore {
  /** Creates the users table if it does not exist. */
  constructor(private readonly db: DatabaseSync) {
    this.db.exec(
      'CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, displayName TEXT NOT NULL UNIQUE)'
    );
  }

  /** Returns the user with the given display name, or null when none exists. */
  async findByName(displayName: string): Promise<User | null> {
    if (typeof displayName !== 'string' || displayName.length === 0) {
      throw new Error('displayName must be a non-empty string');
    }
    const rows = this.db
      .prepare('SELECT id, displayName FROM users WHERE displayName = ?')
      .all(displayName) as unknown as { id: string; displayName: string }[];
    const row = rows[0];
    return row ? new User(row.id, row.displayName) : null;
  }

  /** Inserts a new user or updates the stored user with the same id; throws when the display name is taken by another user. */
  async save(user: User): Promise<User> {
    if (typeof user.id !== 'string' || user.id.length === 0) {
      throw new Error('user id must be a non-empty string');
    }
    const existing = this.db
      .prepare('SELECT id FROM users WHERE id = ?')
      .get(user.id) as unknown as { id: string } | undefined;
    if (existing) {
      this.db
        .prepare('UPDATE users SET displayName = ? WHERE id = ?')
        .run(user.displayName, user.id);
    } else {
      this.db
        .prepare('INSERT INTO users (id, displayName) VALUES (?, ?)')
        .run(user.id, user.displayName);
    }
    return new User(user.id, user.displayName);
  }

  /** Returns the user with the given id, or null when none exists; throws when the id is empty. */
  async findById(id: string): Promise<User | null> {
    if (typeof id !== 'string' || id.length === 0) {
      throw new Error('id must be a non-empty string');
    }
    const rows = this.db
      .prepare('SELECT id, displayName FROM users WHERE id = ?')
      .all(id) as unknown as { id: string; displayName: string }[];
    const row = rows[0];
    return row ? new User(row.id, row.displayName) : null;
  }
}

import { Currency } from '../auction-api/Currency.js';

const API_BASE = 'https://api.frankfurter.app';
const CACHE_TTL_MS = 60 * 60 * 1000;

interface CacheEntry {
  fetchedAt: number;
  rates: Record<string, number>;
}

/**
 * Fetches exchange rates from the Frankfurter API and caches them in memory for one hour.
 * @trace DSN-026 REQ-005 REQ-010
 */
export class FrankfurterClient {
  private readonly cache = new Map<Currency, CacheEntry>();

  /** Returns rates for the base currency, from cache within one hour, else from Frankfurter; returns an empty record when Frankfurter is unreachable and no valid cache exists. Throws Error when the base currency is unsupported. */
  async fetchRates(base: Currency): Promise<Record<string, number>> {
    if (!(Object.values(Currency) as string[]).includes(base)) {
      throw new Error(`Unsupported base currency ${String(base)}`);
    }
    const now = Date.now();
    const cached = this.cache.get(base);
    if (cached && now - cached.fetchedAt < CACHE_TTL_MS) {
      return { ...cached.rates };
    }
    try {
      const response = await fetch(`${API_BASE}/latest?from=${base}`);
      if (!response.ok) {
        throw new Error(`Frankfurter responded with status ${response.status}`);
      }
      const body = (await response.json()) as { rates?: Record<string, number> };
      const rates = body.rates ?? {};
      this.cache.set(base, { fetchedAt: now, rates });
      return { ...rates };
    } catch {
      return {};
    }
  }
}

import { EventFeed } from './EventFeed.js';
import { Bid } from './Bid.js';
import { Item } from './Item.js';

/**
 * Publishes accepted bid events to the internal ws event feed.
 * @trace DSN-031 REQ-003 REQ-007 REQ-011
 */
export class BidEventPublisher {
  constructor(private readonly eventFeed: EventFeed) {}

  /** Publishes an accepted bid to the item's topic; throws when the bid or item is missing its id. */
  async publishBidAccepted(bid: Bid, item: Item): Promise<void> {
    if (typeof item.id !== 'string' || item.id.length === 0) {
      throw new Error('item id must be a non-empty string');
    }
    if (typeof bid.id !== 'string' || bid.id.length === 0) {
      throw new Error('bid id must be a non-empty string');
    }
    const payload = JSON.stringify({
      bidId: bid.id,
      itemId: item.id,
      bidderId: bid.bidderId,
      amount: bid.amount,
      placedAt: bid.placedAt.toISOString(),
      highestBidAmount: item.highestBidAmount,
      highestBidderId: item.highestBidderId,
      endTime: item.endTime.toISOString(),
    });
    this.eventFeed.publish(`item:${item.id}`, payload);
  }
}

import { Item } from './Item.js';
import { EventFeed } from './EventFeed.js';

/**
 * Publishes auction closed events to the internal ws event feed.
 *
 * @trace DSN-030 REQ-003 REQ-004 REQ-007
 */
export class AuctionEventPublisher {
  constructor(private readonly eventFeed: EventFeed) {}

  /** Publishes the closed state, winner and final bid of an item; throws if the item has no id. */
  async publishAuctionClosed(item: Item): Promise<void> {
    if (typeof item.id !== 'string' || item.id.length === 0) {
      throw new Error('item id must be a non-empty string');
    }
    const payload = JSON.stringify({
      itemId: item.id,
      status: item.status,
      winnerId: item.winnerId,
      highestBidAmount: item.highestBidAmount,
      highestBidderId: item.highestBidderId,
      currency: item.currency,
    });
    this.eventFeed.publish(`item.${item.id}.closed`, payload);
  }
}

