  /** Returns true when the status is open and the end time has not been reached at the given moment. */
  isOpen(now: Date): boolean {
    return this.status === AuctionStatus.open && now.getTime() < this.endTime.getTime();
  }

  /** Returns the lowest amount accepted as the next bid: the starting price, or one unit above the highest bid. */
  minimumBid(): number {
    if (this.highestBidAmount === null) {
      return this.startingPrice;
    }
    return this.highestBidAmount + 1;
  }

  /** Moves the end time 2 minutes later when now is within the last 2 minutes before it; throws when the item is not open. */
  extendIfLate(now: Date): boolean {
    if (this.status !== AuctionStatus.open) {
      throw new Error(`Item ${this.id} is not open`);
    }
    const remaining = this.endTime.getTime() - now.getTime();
    if (remaining < 0 || remaining > LATE_BID_WINDOW_MS) {
      return false;
    }
    this.endTime = new Date(this.endTime.getTime() + LATE_BID_WINDOW_MS);
    return true;
  }
