{
  "path": "src/auction-api/EventFeed.ts",
  "content": "import { WebSocketServer, WebSocket } from 'ws';

/**
 * Internal ws endpoint on the API server that fans every published event out to all connected live server instances.
 *
 * @trace DSN-034 REQ-003 REQ-007 REQ-011
 */
export class EventFeed {
  private readonly clients = new Set<WebSocket>();
  private readonly server: WebSocketServer;

  constructor() {
    const port = Number(process.env.EVENT_FEED_PORT ?? 8081);
    this.server = new WebSocketServer({ port });
    this.server.on('connection', (socket: WebSocket) => {
      this.clients.add(socket);
      socket.on('close', () => this.clients.delete(socket));
      socket.on('error', () => this.clients.delete(socket));
    });
  }

  /** Sends the topic and payload to every connected instance; throws an Error when topic or payload is not a string or the topic is empty. */
  publish(topic: string, payload: string): void {
    if (typeof topic !== 'string' || topic.length === 0) {
      throw new Error('topic must be a non-empty string');
    }
    if (typeof payload !== 'string') {
      throw new Error('payload must be a string');
    }
    const message = JSON.stringify({ topic, payload });
    for (const socket of this.clients) {
      if (socket.readyState === WebSocket.OPEN) {
        socket.send(message);
      }
    }
  }
}
"
}

{
  "path": "src/live-updates/EventFeedClient.ts",
  "content": "import WebSocket from 'ws';
import { LiveGateway } from './LiveGateway.js';

const DEFAULT_API_SERVER_URL = 'ws://localhost:8080';
const FEED_PATH = '/internal/live-update-server';
const RECONNECT_DELAY_MS = 1000;

/**
 * Client of the API server's internal ws event feed that hands incoming events to the live gateway.
 * @trace DSN-032 REQ-003 REQ-007 REQ-011
 */
export class EventFeedClient {
  private socket: WebSocket | undefined = undefined;
  private closing = false;

  constructor(private readonly liveGateway: LiveGateway) {}

  /** Opens the ws feed to the API server and keeps reconnecting after a drop. */
  connect(): void {
    this.closing = false;
    const baseUrl = process.env.API_SERVER_URL ?? DEFAULT_API_SERVER_URL;
    const socket = new WebSocket(new URL(FEED_PATH, baseUrl).toString());
    this.socket = socket;

    socket.on('message', (data: WebSocket.RawData) => {
      try {
        const event = JSON.parse(data.toString()) as { topic?: unknown; payload?: unknown };
        if (typeof event.topic !== 'string' || typeof event.payload !== 'string') {
          throw new Error('Event must have string topic and payload');
        }
        this.onEvent(event.topic, event.payload);
      } catch (error) {
        console.error(`Dropped invalid event: ${(error as Error).message}`);
      }
    });

    socket.on('close', () => {
      this.socket = undefined;
      if (!this.closing) {
        setTimeout(() => this.connect(), RECONNECT_DELAY_MS);
      }
    });

    socket.on('error', (error: Error) => {
      console.error(`Event feed error: ${error.message}`);
    });
  }

  /** Hands a bid event to the gateway for every client watching the topic item; throws when topic or payload is empty. */
  onEvent(topic: string, payload: string): void {
    if (typeof topic !== 'string' || topic.trim() === '') {
      throw new Error('topic must be a non-empty string');
    }
    if (typeof payload !== 'string' || payload === '') {
      throw new Error('payload must be a non-empty string');
    }
    this.liveGateway.broadcast(topic, payload);
  }
}
"
}

{
  "path": "src/live-updates/LiveGateway.ts",
  "content": "import { WebSocket } from 'ws';

/**
 * WebSocket gateway for browsers that sends each broadcast only to the sockets watching that item.
 *
 * @trace DSN-033 REQ-003 REQ-009 REQ-011 REQ-004
 */
export class LiveGateway {
  private watchers: Map<string, Set<string>> = new Map();

  constructor(public sockets: Map<string, WebSocket>) {}

  /** Registers a client as watching an item; throws if the input is invalid or the client has no open socket. */
  watch(clientId: string, itemId: string): void {
    this.checkId(clientId, 'clientId');
    this.checkId(itemId, 'itemId');
    if (!this.sockets.has(clientId)) {
      throw new Error(`Client ${clientId} not found`);
    }
    let clients = this.watchers.get(itemId);
    if (!clients) {
      clients = new Set();
      this.watchers.set(itemId, clients);
    }
    clients.add(clientId);
  }

  /** Removes a client from the watchers of an item; throws if the input is invalid. */
  unwatch(clientId: string, itemId: string): void {
    this.checkId(clientId, 'clientId');
    this.checkId(itemId, 'itemId');
    const clients = this.watchers.get(itemId);
    if (!clients) {
      return;
    }
    clients.delete(clientId);
    if (clients.size === 0) {
      this.watchers.delete(itemId);
    }
  }

  /** Sends a message to every open socket watching the item; throws if the input is invalid. */
  broadcast(itemId: string, message: string): void {
    this.checkId(itemId, 'itemId');
    if (typeof message !== 'string') {
      throw new Error('message must be a string');
    }
    const clients = this.watchers.get(itemId);
    if (!clients) {
      return;
    }
    for (const clientId of clients) {
      const socket = this.sockets.get(clientId);
      if (socket && socket.readyState === WebSocket.OPEN) {
        socket.send(message);
      }
    }
  }

  private checkId(value: string, name: string): void {
    if (typeof value !== 'string' || value.length === 0) {
      throw new Error(`${name} must be a non-empty string`);
    }
  }
}
"
}

