import { User } from './User.js';

/**
 * Stores users in the API server's SQLite database, keyed by id and unique by display name.
 * @trace DSN-028 REQ-008
 */
export class UserStore {
  /** Creates the users table if it does not exist. */
  constructor(private readonly db: DatabaseSync) {
    this.db.exec(
      'CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, displayName TEXT NOT NULL UNIQUE)'
    );
  }

  /** Returns the user with the given display name, or null when none exists. */
  async findByName(displayName: string): Promise<User | null> {
    if (typeof displayName !== 'string' || displayName.length === 0) {
      throw new Error('displayName must be a non-empty string');
    }
    const rows = this.db
      .prepare('SELECT id, displayName FROM users WHERE displayName = ?')
      .all(displayName) as unknown as { id: string; displayName: string }[];
    const row = rows[0];
    return row ? new User(row.id, row.displayName) : null;
  }

  /** Inserts a new user or updates the stored user with the same id; throws when the display name is taken by another user. */
  async save(user: User): Promise<User> {
    if (typeof user.id !== 'string' || user.id.length === 0) {
      throw new Error('user id must be a non-empty string');
    }
    const existing = this.db
      .prepare('SELECT id FROM users WHERE id = ?')
      .get(user.id) as unknown as { id: string } | undefined;
    if (existing) {
      this.db
        .prepare('UPDATE users SET displayName = ? WHERE id = ?')
        .run(user.displayName, user.id);
    } else {
      this.db
        .prepare('INSERT INTO users (id, displayName) VALUES (?, ?)')
        .run(user.id, user.displayName);
    }
    return new User(user.id, user.displayName);
  }

  /** Returns the user with the given id, or null when none exists; throws when the id is empty. */
  async findById(id: string): Promise<User | null> {
    if (typeof id !== 'string' || id.length === 0) {
      throw new Error('id must be a non-empty string');
    }
    const rows = this.db
      .prepare('SELECT id, displayName FROM users WHERE id = ?')
      .all(id) as unknown as { id: string; displayName: string }[];
    const row = rows[0];
    return row ? new User(row.id, row.displayName) : null;
  }
}
