{
  "path": "src/exchange-rates/FrankfurterClient.ts",
  "content": "import { Currency } from '../auction-api/Currency.js';

const API_BASE = 'https://api.frankfurter.app';
const CACHE_TTL_MS = 60 * 60 * 1000;

interface CacheEntry {
  fetchedAt: number;
  rates: Record<string, number>;
}

/**
 * Fetches exchange rates from the Frankfurter API and caches them in memory for one hour.
 * @trace DSN-026 REQ-005 REQ-010
 */
export class FrankfurterClient {
  private readonly cache = new Map<Currency, CacheEntry>();

  /** Returns rates for the base currency, from cache within one hour, else from Frankfurter; returns an empty record when Frankfurter is unreachable and no valid cache exists. Throws Error when the base currency is unsupported. */
  async fetchRates(base: Currency): Promise<Record<string, number>> {
    if (!(Object.values(Currency) as string[]).includes(base)) {
      throw new Error(`Unsupported base currency ${String(base)}`);
    }
    const now = Date.now();
    const cached = this.cache.get(base);
    if (cached && now - cached.fetchedAt < CACHE_TTL_MS) {
      return { ...cached.rates };
    }
    try {
      const response = await fetch(`${API_BASE}/latest?from=${base}`);
      if (!response.ok) {
        throw new Error(`Frankfurter responded with status ${response.status}`);
      }
      const body = (await response.json()) as { rates?: Record<string, number> };
      const rates = body.rates ?? {};
      this.cache.set(base, { fetchedAt: now, rates });
      return { ...rates };
    } catch {
      return {};
    }
  }
}
"
}

