import { createServer } from 'node:http';
import express from 'express';
import { WebSocketServer, type WebSocket } from 'ws';
import { LiveGateway } from '../live-updates/LiveGateway.js';
import { EventFeedClient } from '../live-updates/EventFeedClient.js';

const liveGateway = new LiveGateway(new Map<string, WebSocket>());
const eventFeedClient = new EventFeedClient(liveGateway);

const app = express();
app.get('/health', (_req, res) => {
  res.json({ status: 'ok' });
});

const server = createServer(app);
const wss = new WebSocketServer({ server, path: '/' });

// Topics are item:<id>, the same as the API server publishes. Kept here to unwatch on close.
const watched = new Map<string, Set<string>>();

// Browser messages: { type: 'watch' | 'unwatch', itemId }
wss.on('connection', (socket: WebSocket) => {
  const clientId = randomUUID();
  liveGateway.sockets.set(clientId, socket);
  watched.set(clientId, new Set());
  socket.on('message', (data) => {
    try {
      const msg = JSON.parse(data.toString()) as { type?: string; itemId?: string };
      const topic = `item:${msg.itemId}`;
      if (msg.type === 'watch') {
        liveGateway.watch(clientId, topic);
        watched.get(clientId)?.add(topic);
      } else if (msg.type === 'unwatch') {
        liveGateway.unwatch(clientId, topic);
        watched.get(clientId)?.delete(topic);
      }
    } catch (error) {
      socket.send(JSON.stringify({ error: (error as Error).message }));
    }
  });
  socket.on('close', () => {
    for (const topic of watched.get(clientId) ?? []) liveGateway.unwatch(clientId, topic);
    watched.delete(clientId);
    liveGateway.sockets.delete(clientId);
  });
});

const port = Number(process.env.LIVE_UPDATE_SERVER_PORT ?? 8081);
server.listen(port, () => {
  console.log(`Live update server listening on port ${port}`);
});
eventFeedClient.connect();

